pm.test("Login should return 200", () => {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

pm.test("Access token should be generated", () => {
    pm.expect(response.accessToken).to.be.a("string");
    pm.expect(response.accessToken.length).to.be.above(0);
});

pm.test("Refresh token should be generated", () => {
    pm.expect(response.refreshToken).to.be.a("string");
    pm.expect(response.refreshToken.length).to.be.above(0);
});

pm.test("User ID should be generated", () => {
    pm.expect(response.id).to.be.a("number");
});

pm.test("Username should match login credentials", () => {
    pm.expect(response.username).to.eql("emilys");
});

// Save integration workflow data
pm.environment.set("integration_access_token", response.accessToken);
pm.environment.set("integration_refresh_token", response.refreshToken);
pm.environment.set("integration_user_id", response.id);

pm.test("Authenticated user API should return 200", () => {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

const expectedUserId = Number(
    pm.environment.get("integration_user_id")
);

pm.test("Authenticated user ID should match login user ID", () => {
    pm.expect(response.id).to.eql(expectedUserId);
});

pm.test("Username should match login user", () => {
    pm.expect(response.username).to.eql("emilys");
});

pm.test("User email should be valid", () => {
    pm.expect(response.email).to.be.a("string");
    pm.expect(response.email).to.match(
        /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    );
});

pm.test("User profile should contain required fields", () => {
    pm.expect(response.firstName).to.be.a("string");
    pm.expect(response.lastName).to.be.a("string");
    pm.expect(response.gender).to.be.a("string");
});

console.log("Authenticated User:", response.username);
console.log("Verified User ID:", response.id);

pm.test("Get user carts API should return 200", () => {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

const expectedUserId = Number(
    pm.environment.get("integration_user_id")
);

pm.test("Response should contain carts array", () => {
    pm.expect(response.carts).to.be.an("array");
});

pm.test("Cart ownership should match authenticated user", () => {
    response.carts.forEach(cart => {
        pm.expect(cart.userId).to.eql(expectedUserId);
    });
});

pm.test("Each cart should contain valid products", () => {
    response.carts.forEach(cart => {
        pm.expect(cart.products).to.be.an("array");

        cart.products.forEach(product => {
            pm.expect(product.id).to.be.a("number");
            pm.expect(product.quantity).to.be.a("number");
            pm.expect(product.price).to.be.a("number");
        });
    });
});

pm.test("Cart totals should be valid", () => {
    response.carts.forEach(cart => {
        pm.expect(cart.total).to.be.a("number");
        pm.expect(cart.totalQuantity).to.be.a("number");
        pm.expect(cart.totalProducts).to.be.a("number");
    });
});

console.log("Authenticated User ID:", expectedUserId);
console.log("Carts Retrieved:", response.carts.length);

pm.test("Product API should return 200", () => {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

pm.test("Product ID should be valid", () => {
    pm.expect(response.id).to.eql(1);
});

pm.test("Product title should be available", () => {
    pm.expect(response.title).to.be.a("string");
    pm.expect(response.title.length).to.be.above(0);
});

pm.test("Product price should be positive", () => {
    pm.expect(response.price).to.be.a("number");
    pm.expect(response.price).to.be.above(0);
});

pm.test("Product stock should be valid", () => {
    pm.expect(response.stock).to.be.a("number");
    pm.expect(response.stock).to.be.at.least(0);
});

// Save product information for the next request
pm.environment.set("integration_product_id", response.id);
pm.environment.set("integration_product_price", response.price);
pm.environment.set("integration_product_title", response.title);

console.log("Product ID:", response.id);
console.log("Product Price:", response.price);

pm.test("Add cart API should return 200 or 201", () => {
    pm.expect([200, 201]).to.include(pm.response.code);
});

const response = pm.response.json();

const expectedProductId = Number(
    pm.environment.get("integration_product_id")
);

pm.test("Cart ID should be generated", () => {
    pm.expect(response.id).to.be.a("number");
    pm.expect(response.id).to.be.above(0);
});

pm.test("Cart should belong to user 1", () => {
    pm.expect(response.userId).to.eql(1);
});

pm.test("Cart should contain the requested product", () => {
    pm.expect(response.products).to.be.an("array");

    const product = response.products.find(
        item => item.id === expectedProductId
    );

    pm.expect(product).to.exist;
    pm.expect(product.quantity).to.eql(2);
});

pm.test("Cart quantity should be correct", () => {
    pm.expect(response.totalQuantity).to.eql(2);
});

// Save generated cart ID
pm.environment.set("integration_cart_id", response.id);

console.log("Created Cart ID:", response.id);
console.log("Added Product ID:", expectedProductId);

pm.test("GET created cart returns expected not-found response", () => {
    pm.expect(pm.response.code).to.eql(404);
});

const response = pm.response.json();

pm.test("Error message should identify missing cart", () => {
    pm.expect(response.message).to.include(
        pm.environment.get("integration_cart_id")
    );
});

console.log("Generated cart ID:",
    pm.environment.get("integration_cart_id"));

console.log("Persistence limitation confirmed");

