pm.test("Exchange rate API should return 200", () => {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

// Read the rate directly from the current API response
const exchangeRate = Number(response.rate);

const amountUSD = 100;

// Validate exchange rate
pm.test("Exchange rate should be valid", () => {
    pm.expect(exchangeRate).to.be.a("number");
    pm.expect(exchangeRate).to.be.above(0);
});

// Calculate INR
const actualINR = Number(
    (amountUSD * exchangeRate).toFixed(2)
);

// Independently calculate expected result
const expectedINR = Number(
    (amountUSD * Number(response.rate)).toFixed(2)
);

pm.test("USD to INR calculation should be correct", () => {
    pm.expect(actualINR).to.eql(expectedINR);
});

pm.test("Converted amount should be positive", () => {
    pm.expect(actualINR).to.be.above(0);
});

// Save results
pm.environment.set("integration_exchange_rate", exchangeRate);
pm.environment.set("integration_amount_usd", amountUSD);
pm.environment.set("integration_amount_inr", actualINR);

console.log("USD Amount:", amountUSD);
console.log("Exchange Rate:", exchangeRate);
console.log("INR Amount:", actualINR);
